target.css:
:root {
  --cream: #fdf6ec;
  --pink: #e8637a;
  --dark-brown: #3b2012;
  --light-pink: #fce8ed;
  --gold: #c9883a;
  --divider: #f2d0b0;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
}

.flavor-tag {
  background-color: var(--cream);
  border: 3px solid var(--pink);
  border-radius: 16px;
  width: 300px;
  padding: 18px 22px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.tag-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 2px dashed var(--divider);
  padding-bottom: 10px;
}

.parlor-name {
  font-size: 15px;
  font-weight: 700;
  color: var(--pink);
  letter-spacing: 0.04em;
}

.est {
  font-size: 11px;
  font-weight: 600;
  color: var(--gold);
  letter-spacing: 0.06em;
}

.flavor-name {
  font-size: 22px;
  font-weight: 800;
  color: var(--dark-brown);
  text-align: center;
  letter-spacing: 0.02em;
}

.flavor-details {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.detail-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background-color: var(--light-pink);
  border-radius: 8px;
  padding: 5px 10px;
}

.label {
  font-size: 11px;
  font-weight: 700;
  color: var(--gold);
  text-transform: uppercase;
  letter-spacing: 0.07em;
}

.value {
  font-size: 13px;
  font-weight: 600;
  color: var(--dark-brown);
}

.tag-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-top: 2px dashed var(--divider);
  padding-top: 10px;
}

.scoop-count {
  font-size: 12px;
  font-weight: 600;
  color: var(--pink);
}

.price {
  font-size: 18px;
  font-weight: 800;
  color: var(--dark-brown);
}
